style:
* {
     color: rgba(0,0,0,1.0);
     overflow-wrap: break-word;
}
a {
     font-style: normal;
     font-weight: normal;
     color: rgba(0,120,194,1.0);
}
a.timecode {
     color: #669900;
}
img, iframe {
     display: block;
     margin: 10 auto;
     max-width: 100%;
     height: auto;
}
body {
     padding: 21px 21px 21px 21px;
}
p#apNoShownotes {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    -webkit-text-size-adjust: none;
}
